/**
 * Entry point of the main process. Required order:
 * userData → log → before-ready (scheme, open-file, single instance) → ready → services → IPC → window.
 * Domains do not edit this file: they fill in their `<domain>/init.ts` and `ipc/handlers/<domain>.ts`.
 */
import { BrowserWindow, app, ipcMain, nativeTheme } from 'electron'
import { readFlags } from './bootstrap/env'
import { readInitialPrefs } from './bootstrap/initial-prefs'
import { initLog } from './bootstrap/log'
import { installPerfMarks } from './bootstrap/perf'
import { preReady } from './bootstrap/pre-ready'
import { installDefaultSessionPolicy, installSecurity } from './bootstrap/security'
import {
  SERVICES,
  SERVICE_DOMAINS,
  initServices,
  serviceForChannel,
  type ServiceDomain,
  type ServicesHandle,
} from './bootstrap/services'
import { configureUserData } from './bootstrap/user-data'
import { handlers } from './ipc/handlers'
import { makeEmitter, makeSenderCheck, registerRpc } from './ipc/router'
import {
  createMainWindow,
  getMainWindow,
  installQuitHandshake,
  rendererIndexPath,
} from './windows/main-window'

const userData = configureUserData()
const log = initLog()
const flags = readFlags()
const isDev = !app.isPackaged

const { gotLock } = preReady()

if (gotLock) {
  installSecurity()
  let services: ServicesHandle | null = null

  installQuitHandshake(async () => {
    await services?.dispose()
  })

  app.on('window-all-closed', () => {
    // macOS: closing the last window does not quit (global shortcut always active).
    if (process.platform !== 'darwin') app.quit()
  })

  void app.whenReady().then(async () => {
    installDefaultSessionPolicy()
    nativeTheme.themeSource = readInitialPrefs(userData).theme

    const emit = makeEmitter({
      targets: () => BrowserWindow.getAllWindows().map((w) => w.webContents),
      validate: isDev,
      onError: (event, err) => log.error(`[ipc] invalid event ${event}`, err),
    })

    // The window opens as soon as the preferences are read (language, theme), while the other
    // services start: the renderer loads in parallel, each call waits for the service it needs.
    const gates = new Map<ServiceDomain | 'all', { done: boolean; promise: Promise<void> }>()
    const opens = new Map<ServiceDomain | 'all', () => void>()
    for (const d of [...SERVICE_DOMAINS, 'all'] as const) {
      const gate = { done: false, promise: Promise.resolve() }
      gate.promise = new Promise<void>((resolve) => {
        opens.set(d, () => {
          gate.done = true
          resolve()
        })
      })
      gates.set(d, gate)
    }
    registerRpc({
      ipcMain,
      readyFor: (channel) => {
        const need = serviceForChannel(channel)
        const gate = need ? gates.get(need) : undefined
        return gate && !gate.done ? gate.promise : null
      },
      handlers,
      validateOutput: isDev,
      isAllowedSender: makeSenderCheck({
        rendererUrl: flags.rendererUrl,
        rendererIndexPath: rendererIndexPath(),
      }),
      onError: (channel, err) => log.error(`[ipc] ${channel}`, err),
    })
    installPerfMarks(userData)

    // `--uninstall-native-hosts` (bridge) quits during the services: no early window in that case.
    const early = !process.argv.includes('--uninstall-native-hosts')
    const openWindow = () => {
      if (!getMainWindow()) createMainWindow({ userData, flags })
    }
    try {
      services = await initServices(
        { userData, flags, isPackaged: app.isPackaged, getMainWindow, emit, log },
        SERVICES,
        (domain) => {
          opens.get(domain)?.()
          if (early && domain === 'prefs') openWindow()
        },
      )
    } finally {
      for (const open of opens.values()) open()
    }

    openWindow()

    app.on('activate', () => {
      if (!getMainWindow()) createMainWindow({ userData, flags })
    })
  })
}
